#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    int total = 1 << n;
    for(int i = 0; i < total; i++){
        int g = i ^ (i >> 1);
        string s(n, '0');
        for(int b = 0; b < n; b++){
            if(g & (1 << (n-1-b))) s[b] = '1';
        }
        cout << s << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
ull solve(ull l, ull r){
    ull x = l;
    for(int b = 0; b < 63; b++){
        ull bit = 1ULL << b;
        if(!(x & bit)){
            ull cand = x | bit;
            if(cand <= r) x = cand;
            else break;
        }
    }
    return x;
}
int main(){
    int q; cin >> q;
    while(q--){
        ull l, r; cin >> l >> r;
        cout << solve(l, r) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
const int MAXM = 2005;
int n, m;
vector<string> t;
// notEqual[k][c] = bitset over the m strings: bit j set if t[j][k] != character ('a'+c)
vector<array<bitset<MAXM>, 26>> notEqual;

bool check(const string &cand){
    bitset<MAXM> atLeastOne, atLeastTwo;
    for(int k = 0; k < n; k++){
        const bitset<MAXM> &cur = notEqual[k][cand[k]-'a'];
        atLeastTwo |= (atLeastOne & cur);
        atLeastOne |= cur;
    }
    return atLeastTwo.none();
}

int main(){
    cin >> m >> n; // m strings, each of length n
    t.resize(m);
    for(auto &s : t) cin >> s;
    notEqual.assign(n, array<bitset<MAXM>,26>());
    for(int k = 0; k < n; k++){
        for(int j = 0; j < m; j++){
            int c = t[j][k]-'a';
            for(int ch = 0; ch < 26; ch++){
                if(ch != c) notEqual[k][ch][j] = 1;
            }
        }
    }
    // candidate 1: t[0] unchanged
    if(check(t[0])){ cout << t[0] << "\n"; return 0; }
    // try every single-position substitution of t[0]
    string cand = t[0];
    for(int pos = 0; pos < n; pos++){
        char orig = cand[pos];
        for(char ch = 'a'; ch <= 'z'; ch++){
            if(ch == orig) continue;
            cand[pos] = ch;
            if(check(cand)){ cout << cand << "\n"; return 0; }
        }
        cand[pos] = orig;
    }
    cout << -1 << "\n";
}

#include <bits/stdc++.h>
using namespace std;
const int MAXP = 2005;
int main(){
    string text, pattern;
    cin >> text >> pattern;
    int n = text.size(), m = pattern.size();
    array<bitset<MAXP>, 26> B;
    for(int c = 0; c < 26; c++) B[c].reset();
    for(int j = 0; j < m; j++){
        B[pattern[j]-'a'][j] = 1;
    }
    bitset<MAXP> D; // D.reset() by default
    vector<int> starts;
    for(int i = 0; i < n; i++){
        D = ((D << 1) | bitset<MAXP>(1)) & B[text[i]-'a'];
        if(m >= 1 && D[m-1]){
            starts.push_back(i - m + 1);
        }
    }
    cout << starts.size() << "\n";
    for(size_t k = 0; k < starts.size(); k++){
        cout << starts[k] << (k+1<starts.size()? ' ' : '\n');
    }
}
